<?php $__env->startPush('scripts'); ?><script>
const p=<?php echo json_encode($products->map(fn($x)=>['id'=>$x->id, 'name'=>$x->name, 'price'=>(float)$x->selling_price])->values()) ?>;
const initial=<?php echo json_encode(old('items', isset($quotation) ? $quotation->items->map(fn($x)=>['product_id'=>$x->product_id, 'quantity'=>(float)$x->quantity) ?>;
let i=0;function add(row={}){let tr=document.createElement('tr');tr.innerHTML=`<td><select class="form-select prod" name="items[${i}][product_id]" required><option value="">Select</option>${p.map(x=>`<option value="${x.id}" ${String(x.id)===String(row.product_id||'')?'selected':''}>${x.name}</option>`).join('')}</select></td><td><input class="form-control" name="items[${i}][quantity]" type="number" step="0.0001" min="0.0001" value="${row.quantity??1}"></td><td><input class="form-control price" name="items[${i}][unit_price]" type="number" step="0.0001" min="0" value="${row.unit_price??0}"></td><td><input class="form-control" name="items[${i}][discount]" type="number" step="0.01" min="0" value="${row.discount??0}"></td><td><input class="form-control" name="items[${i}][tax]" type="number" step="0.01" min="0" value="${row.tax??0}"></td><td><button type="button" class="btn btn-outline-danger btn-sm">×</button></td>`;tr.querySelector('.prod').onchange=e=>{let x=p.find(y=>String(y.id)===e.target.value);if(x&&!row.unit_price)tr.querySelector('.price').value=x.price};tr.querySelector('button').onclick=()=>tr.remove();document.querySelector('#qt tbody').appendChild(tr);i++}document.getElementById('add').onclick=()=>add();(initial.length?initial:[{}]).forEach(add);
</script><?php $__env->stopPush(); ?>

